const { cliente_id, telefone, args = {} } = $json;
const tipo = String(args.tipo ?? '').toLowerCase().trim();
const placa = String(args.placa ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
if (tipo !== 'data' && tipo !== 'km') return [{ json: { invalido: true, motivo: 'tipo_invalido' } }];
if (placa && !/^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$/.test(placa)) return [{ json: { invalido: true, motivo: 'placa_invalida' } }];
let meses = null, data = null, km = null;
if (tipo === 'km') {
  km = Number(String(args.km ?? '').replace(/\D/g, ''));
  if (!km || km < 1000) return [{ json: { invalido: true, motivo: 'km_invalido' } }];
} else if (args.meses !== undefined && args.meses !== '') {
  meses = Number(args.meses);
  if (!Number.isInteger(meses) || meses < 1 || meses > 36) return [{ json: { invalido: true, motivo: 'meses_invalido' } }];
} else {
  data = String(args.data ?? '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) return [{ json: { invalido: true, motivo: 'data_invalida' } }];
}
return [{ json: { cliente_id, telefone, tipo, placa, meses, data, km } }];

const entrada = $('Validar args').item.json;
if (entrada.invalido) {
  const msgs = {
    tipo_invalido: 'Quer ser lembrado por data ou por km?',
    placa_invalida: 'Não entendi a placa. Pode mandar de novo?',
    km_invalido: 'Não entendi a quilometragem. Quantos km você quer pro aviso?',
    meses_invalido: 'Não entendi o prazo. Daqui quantos meses?',
    data_invalida: 'Não entendi a data. Pode mandar no formato dia/mês?'
  };
  return [{ json: { texto: msgs[entrada.motivo] ?? 'Faltou algum dado pro lembrete.', dados: { erro: entrada.motivo } } }];
}
if ($json.erro) {
  return [{ json: { texto: 'Não consegui registrar o lembrete agora. Quer que eu chame um atendente?', dados: { erro: $json.erro } } }];
}
let quando;
if (entrada.tipo === 'km') quando = `quando o carro chegar em ${entrada.km} km`;
else if (entrada.meses) quando = `daqui ${entrada.meses} ${entrada.meses === 1 ? 'mês' : 'meses'}`;
else quando = `em ${entrada.data}`;
return [{ json: { texto: `Show, anotado! Te aviso ${quando}.`, dados: { lembrete_id: $json.lembrete_id ?? null, tipo: entrada.tipo, meses: entrada.meses, data: entrada.data, km: entrada.km, placa: entrada.placa } } }];
